from typing import List

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        counts = {0: 1}
        for num in nums:
            nxt = {}
            for total, ways in counts.items():
                nxt[total + num] = nxt.get(total + num, 0) + ways
                nxt[total - num] = nxt.get(total - num, 0) + ways
            counts = nxt
        return counts.get(target, 0)

